<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$dbn=getenv('DB_NAME')?:'sukamulya_ui_test';if($dbn!=='sukamulya_ui_test')throw new RuntimeException('Only isolated sukamulya_ui_test allowed');
$db=new mysqli('localhost','root','',$dbn);$base='http://127.0.0.1:8097/';$tag='uit'.bin2hex(random_bytes(4));$pw=bin2hex(random_bytes(20));$hash=password_hash($pw,PASSWORD_DEFAULT);
foreach(array('admin','operator','auditor') as $role){$name=$tag.'_'.$role;$s=$db->prepare('INSERT INTO admins(username,password_hash,role,is_active) VALUES(?,?,?,1)');$s->bind_param('sss',$name,$hash,$role);$s->execute();}
function verify_ui($ok,$label){if(!$ok)throw new RuntimeException($label);echo 'PASS '.$label.PHP_EOL;}
class OpsHttp{
 public $c,$html,$code,$location;public function __construct(){$this->c=curl_init();curl_setopt_array($this->c,array(CURLOPT_RETURNTRANSFER=>TRUE,CURLOPT_COOKIEFILE=>'',CURLOPT_TIMEOUT=>20,CURLOPT_PROXY=>'',CURLOPT_HEADER=>TRUE));}
 function go($path,$fields=NULL){global $base;if($fields!==NULL){$token='';foreach(curl_getinfo($this->c,CURLINFO_COOKIELIST) as $cookie){$p=explode("\t",$cookie);if(($p[5]??'')==='csrf_sukamulya_cookie')$token=$p[6];}$fields['csrf_sukamulya']=$token;curl_setopt_array($this->c,array(CURLOPT_POST=>TRUE,CURLOPT_POSTFIELDS=>http_build_query($fields)));}else curl_setopt($this->c,CURLOPT_HTTPGET,TRUE);curl_setopt($this->c,CURLOPT_URL,$base.$path);$raw=curl_exec($this->c);$size=curl_getinfo($this->c,CURLINFO_HEADER_SIZE);$head=substr($raw,0,$size);$this->html=substr($raw,$size);$this->code=curl_getinfo($this->c,CURLINFO_HTTP_CODE);$this->location=preg_match('/^Location:\s*(\S+)/mi',$head,$m)?$m[1]:'';return $this;}
 function login($role){global $tag,$pw;$this->go('admin/login');$this->go('admin/login',array('username'=>$tag.'_'.$role,'password'=>$pw));verify_ui(in_array($this->code,array(302,303,307),TRUE),'Login '.$role);return $this;}
 function post($path,$data){$this->go($path);$this->go($path,$data);verify_ui(!preg_match('/Fatal error|A PHP Error|A Database Error|Severity:/',$this->html),'POST no PHP errors '.$path);return $this;}
}
$a=(new OpsHttp())->login('admin');
$a->go('admin/rekonsiliasi');verify_ui($a->code===200&&!preg_match('/A PHP Error|A Database Error|Fatal error/',$a->html),'Reconciliation loads');$html=str_replace(array($tag.'_admin',ucwords(str_replace('_',' ',$tag.'_admin'))),'Admin',$a->html);file_put_contents(__DIR__.'/../tmp/family-preview/admin-reconciliation.html',$html);
$ledger_before=$db->query('SELECT COUNT(*) n,COALESCE(SUM(amount),0) s FROM transactions')->fetch_assoc();
$date='2026-11-08';$expected=(float)$db->query("SELECT COALESCE(SUM(CASE WHEN type='masuk' THEN amount ELSE -amount END),0) s FROM transactions WHERE status='verified' AND tx_date<='$date'")->fetch_assoc()['s'];
$a->post('admin/rekonsiliasi',array('recon_date'=>$date,'bank_balance'=>'123456.78','note'=>'Uji '.$tag));$r=$db->query("SELECT * FROM cash_reconciliations WHERE note='Uji $tag'")->fetch_assoc();verify_ui($r&&abs((float)$r['system_balance']-$expected)<.001&&abs((float)$r['difference']-(123456.78-$expected))<.001,'Server calculates actual verified balance and difference');
$a->post('admin/rekonsiliasi',array('recon_date'=>'2026-10-01','bank_balance'=>'0','note'=>'Tanggal lama '.$tag));$r=$db->query("SELECT * FROM cash_reconciliations WHERE note='Tanggal lama $tag'")->fetch_assoc();$old=(float)$db->query("SELECT COALESCE(SUM(CASE WHEN type='masuk' THEN amount ELSE -amount END),0) s FROM transactions WHERE status='verified' AND tx_date<='2026-10-01'")->fetch_assoc()['s'];verify_ui($r&&abs((float)$r['system_balance']-$old)<.001,'Historical date uses balance up to selected day');
$before=(int)$db->query('SELECT COUNT(*) n FROM cash_reconciliations')->fetch_assoc()['n'];$a->post('admin/rekonsiliasi',array('recon_date'=>'2099-01-01','bank_balance'=>'100'));verify_ui((int)$db->query('SELECT COUNT(*) n FROM cash_reconciliations')->fetch_assoc()['n']===$before,'Future date rejected');$a->post('admin/rekonsiliasi',array('recon_date'=>$date,'bank_balance'=>'invalid'));verify_ui((int)$db->query('SELECT COUNT(*) n FROM cash_reconciliations')->fetch_assoc()['n']===$before,'Nonnumeric balance rejected');verify_ui($db->query('SELECT COUNT(*) n,COALESCE(SUM(amount),0) s FROM transactions')->fetch_assoc()===$ledger_before,'Reconciliation does not alter cash journal');
$aud=(new OpsHttp())->login('auditor');$aud->go('admin/rekonsiliasi');verify_ui($aud->code===200&&strpos($aud->html,'id="recon-form"')===FALSE,'Auditor can read but sees no save form');$aud->go('admin/rekonsiliasi',array('recon_date'=>$date,'bank_balance'=>0));verify_ui($aud->code===403,'Auditor POST denied');$o=(new OpsHttp())->login('operator');$o->go('admin/rekonsiliasi');verify_ui($o->code===403,'Operator access denied');$g=new OpsHttp();$g->go('admin/rekonsiliasi');verify_ui(in_array($g->code,array(302,303,307),TRUE),'Guest redirected');
echo 'All financial mutations were confined to isolated test database.'.PHP_EOL;
